import pyomo.environ as pyo

DATA = {
    "sources": ["solar", "wind", "hydro"],
    "energy": {"solar": 500, "wind": 1000, "hydro": 2000},
    "impact": {"solar": 2, "wind": 3, "hydro": 5},
    "cost": {"solar": 20000, "wind": 35000, "hydro": 80000},
    "area": {"solar": 5, "wind": 15, "hydro": 40},
    "budget": 1000000,
    "area_cap": 5000,
    "solar_energy_share_min": 0.5,
    "min_units": {"solar": 1, "wind": 1, "hydro": 1},
    "objective_energy_mult": 1000,
    "objective_impact_mult": 1000,
}


def build_model(data=None):
    d = data or DATA
    S = list(d["sources"])

    model = pyo.ConcreteModel("renewable_plan")

    model.SRC = pyo.Set(initialize=S, ordered=True)

    def _e(m, s):
        return float(d["energy"][s])

    def _i(m, s):
        return float(d["impact"][s])

    def _c(m, s):
        return float(d["cost"][s])

    def _ar(m, s):
        return float(d["area"][s])

    def _min_u(m, s):
        return int(d["min_units"][s])

    model.unit_energy = pyo.Param(model.SRC, initialize=_e)
    model.unit_impact = pyo.Param(model.SRC, initialize=_i)
    model.unit_cost = pyo.Param(model.SRC, initialize=_c)
    model.unit_area = pyo.Param(model.SRC, initialize=_ar)
    model.unit_floor = pyo.Param(model.SRC, initialize=_min_u)

    model.x = pyo.Var(
        model.SRC,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    def min_units_rule(m, s):
        return m.x[s] >= m.unit_floor[s]

    model.link_min_units = pyo.Constraint(model.SRC, rule=min_units_rule)

    def budget_rule(m):
        return sum(m.unit_cost[s] * m.x[s] for s in m.SRC) <= d["budget"]

    model.link_budget = pyo.Constraint(rule=budget_rule)

    def area_rule(m):
        return sum(m.unit_area[s] * m.x[s] for s in m.SRC) <= d["area_cap"]

    model.link_area = pyo.Constraint(rule=area_rule)

    share_floor = float(d["solar_energy_share_min"])

    def solar_share_rule(m):
        other = sum(m.unit_energy[s] * m.x[s] for s in m.SRC if s != "solar")
        return (1.0 - share_floor) * (
            m.unit_energy["solar"] * m.x["solar"]
        ) >= share_floor * other

    model.link_solar_share = pyo.Constraint(rule=solar_share_rule)

    def obj_rule(m):
        energy_term = sum(
            float(d["objective_energy_mult"]) * m.unit_energy[s] * m.x[s]
            for s in m.SRC
        )
        impact_term = sum(
            float(d["objective_impact_mult"]) * m.unit_impact[s] * m.x[s]
            for s in m.SRC
        )
        return energy_term - impact_term

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    return model


